import groovy.xml.XmlSlurper
import groovy.json.JsonOutput
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

import java.nio.charset.StandardCharsets

def flowFile = session.get()

if (flowFile == null) {
    return
}

try {
    // Read XML content from the incoming FlowFile
    def xmlText = ''

    session.read(flowFile, { inputStream ->
        xmlText = inputStream.getText('UTF-8')
    } as InputStreamCallback)

    // Parse XML
    def xml = new XmlSlurper().parseText(xmlText)

    // Convert Employee elements to JSON objects
    def employees = xml.Employee.collect { emp ->
        [
            employeeId: emp.employeeId.text(),
            name      : emp.name.text(),
            location  : emp.location.text()
        ]
    }

    // Build JSON structure
    def result = [Employees: employees]

    // Convert to formatted JSON
    def jsonText = JsonOutput.prettyPrint(
        JsonOutput.toJson(result)
    )

    // Replace FlowFile content with JSON
    flowFile = session.write(flowFile, { outputStream ->
        outputStream.write(
            jsonText.getBytes(StandardCharsets.UTF_8)
        )
    } as OutputStreamCallback)

    // Change output filename
    flowFile = session.putAttribute(
        flowFile,
        'filename',
        'employee.json'
    )

    // Set MIME type
    flowFile = session.putAttribute(
        flowFile,
        'mime.type',
        'application/json'
    )

    // Route successful FlowFile
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error('Failed to transform XML to JSON', e)

    session.transfer(flowFile, REL_FAILURE)
}
